@startuml

class Department {
  + name : string
}

class ResearchGroup {
  + name : string
}

class Researcher {
  + name : string
}

class Project {
  + name : string
}

class WorkPackage {
  + name : string
}

class Assignment {
  + startDate : date
  + endDate : date
}

Department "1" -- "*" ResearchGroup : belongs to
ResearchGroup "1" -- "1..*" Researcher : belongs to
Project "1" *-- "1..*" WorkPackage : decomposed into
WorkPackage "*" -- "1" ResearchGroup : led by
Researcher "1..*" -- "*" WorkPackage : assigned to

Assignment "1" -- "1" Researcher
Assignment "1" -- "1" WorkPackage

@enduml

